head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setDataType]<br/>Body Column 정보를 사용하여 특정 Body Column 의 dataType 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 dataType 속성을 설정할 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다.",
        "dataType(필수) 파라미터로 'number' 를 설정하여 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'text' 를 설정하여 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'float' 를 설정하여 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'date' 를 설정하여 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터에 4개 값('number','text','float','date') 이외의 값이나 빈 문자열(''), null, undefined 을 설정하면 메소드가 실행되지 않습니다.",
        "options(선택) 파라미터로 추가 옵션을 객체로 설정할 수 있어야 합니다.",
        "options.displayFormat(선택) 파라미터로 Body Column 값이 표시되는 포맷을 마스크 문자로 설정할 수 있어야 합니다. (Body Column 의 displayFormat 속성에 설정됩니다.)",
        "options.displayFormat(선택) 파라미터는 dataType 파라미터값에 따라 설정할 수 있는 마스크 문자가 달라집니다. (dataType='text' : '#' / dataType='date' : 'y','M','d','E' / 그외 : '#','0',',','.')",
        "options.displayFormat 파라미터를 설정하지 않으면 Column 의 displayFormat 속성이 ''(Empty String)으로 강제 설정됩니다.",
        "'euro', 'rupee', 'tenge' 등의 통화 계열 dataType 속성값은 setDataType() 메소드로 설정할 수 없습니다. (통화 타입을 설정하려면 changeCurrency() 메소드를 사용해야 합니다.)",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] col1~col4 컬럼은 Body Column dataType 미설정(바인딩 DataList 의 text 가 반영됨), 두번째 컬럼(인덱스 1, col2)은 숨김 처리\n[절차] columnInfo(인덱스) + dataType (+ displayFormat) 선택 후 setDataType 실행\n[확인] getDataType 으로 변경 전/후 dataType 을, Row 0 표시값으로 displayFormat 반영을 확인"', '', 'label1');

    // dataList 생성 + 바인딩
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // 검증용 초기 데이터 설정 (number/float/date 변환 확인용)
    dlt_bind.setJSON([
        { "col1": "12345", "col2": "67890", "col3": "11.22", "col4": "20251225" }
    ]);

    let properties = { dataList: "data:dlt_bind" };
    let cList = $c.gcm.createCList(properties);

    // target 생성 (기본 4컬럼 col1~col4, Body Column dataType 미설정)
    await $c.gcm.createBasicGridView(cList);

    // 숨겨진 Column 포함 인덱스 검증용으로 두번째 컬럼(인덱스 1) 숨김
    target1.setColumnVisible(1, false);
}



scwin.btn_setDataType_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let dataTypeText = par_dataType.getValue();
    let displayFormat = par_displayFormat.getValue();

    // 변경 전 dataType
    let beforeType = target1.getDataType(columnInfo);

    let dataTypeArg;
    if (dataTypeText === '__empty') {
        dataTypeArg = "";
    } else if (dataTypeText === '__null') {
        dataTypeArg = null;
    } else if (dataTypeText === '__undefined') {
        dataTypeArg = undefined;
    } else {
        dataTypeArg = dataTypeText;
    }

    let callDesc;
    if (displayFormat !== '') {
        // options.displayFormat 설정
        target1.setDataType(columnInfo, dataTypeArg, { displayFormat: displayFormat });
        callDesc = "setDataType(" + columnInfo + ", '" + dataTypeText + "', {displayFormat:'" + displayFormat + "'})";
    } else {
        // options 생략
        target1.setDataType(columnInfo, dataTypeArg);
        callDesc = "setDataType(" + columnInfo + ", '" + dataTypeText + "')";
    }

    wf_body_bottom.getObj("scwin").setReturnValue(callDesc + " | 변경 전 dataType : " + beforeType);

    // 변경 후 확인
    scwin.btn_getDataType_onclick();
}



scwin.btn_getDataType_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    // 변경된 dataType 확인 + displayFormat 반영 결과(셀 표시값)로 확인
    let afterType = target1.getDataType(columnInfo);
    let displayData = target1.getCellDisplayData(0, columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getDataType(" + columnInfo + ") : " + afterType + " | Row 0 표시값 : '" + displayData + "'");
}
